def _extract_annotations(template_dict):
    """Extract annotations (@optional, @annotation_only) from YAML template comments.

    :param template_dict: dict representation of a YAML document (with preserved comments)
    :type template_dict: dict
    :return: dict mapping placeholder paths to annotation types ('optional', 'annotation_only')
    :rtype: dict
    """
    annotations = {}

    def process_dict(d, path_prefix=""):
        if hasattr(d, 'ca') and hasattr(d.ca, 'items'):
            for key in d.keys():
                current_path = f"{path_prefix}.{key}" if path_prefix else key

                # Get comment for this key
                comment_info = d.ca.items.get(key)
                if comment_info and len(comment_info) > 2 and comment_info[2]:
                    comment_text = comment_info[2].value.strip()

                    # Check for annotations
                    if '@optional' in comment_text:
                        annotations[current_path] = 'optional'
                    elif '@annotation_only' in comment_text:
                        annotations[current_path] = 'annotation_only'

                # Process nested dictionaries
                value = d[key]
                if isinstance(value, dict):
                    process_dict(value, current_path)
                elif isinstance(value, list):
                    process_list(value, current_path)

    def process_list(lst, path_prefix=""):
        # Lists can also have comments, but let's focus on dicts for now
        for i, item in enumerate(lst):
            current_path = f"{path_prefix}[{i}]"
            if isinstance(item, dict):
                process_dict(item, current_path)
            elif isinstance(item, list):
                process_list(item, current_path)

    process_dict(template_dict)
    return annotations

